select job_name, to_char(run_time,'MM-DD HH24:MI:SS') t, status, (details->>'response')::jsonb->>'startDate' sd, (details->>'response')::jsonb->>'endDate' ed, (details->>'response')::jsonb->>'gamesTotal' gt, (details->>'response')::jsonb->>'gamesProcessed' gp, (details->>'response')::jsonb->>'failedRows' fr, left((details->>'response')::jsonb->>'errors',400) errs from cron_job_audit where run_time >= '2026-11-13 09:40' and run_time < '2026-11-16 10:30' and job_name = 'ingest-projection-inputs' order by run_time
